import java.util.Scanner;

public class E {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int length = sc.nextInt();
        String sequence = sc.next();
        int[] vIndices = new int[length], kIndices = new int[length], xIndices = new int[length];
        int vCount = 0, kCount = 0, xCount = 0;
        for (int i = 0; i < length; i++) {
            char ch = sequence.charAt(i);
            if (ch == 'V') vIndices[vCount++] = i;
            else if (ch == 'K') kIndices[kCount++] = i;
            else xIndices[xCount++] = i;
        }
        long[][][][] dpArray = new long[length + 1][length + 1][length + 1][2];
        for (int i = 0; i <= length; i++)
            for (int j = 0; j <= length; j++)
                for (int k = 0; k <= length; k++)
                    for (int d = 0; d < 2; d++)
                        dpArray[i][j][k][d] = Long.MAX_VALUE;
        dpArray[0][0][0][0] = 0;
        for (int vIdx = 0; vIdx <= vCount; vIdx++) {
            for (int kIdx = 0; kIdx <= kCount; kIdx++) {
                for (int xIdx = 0; xIdx <= xCount; xIdx++) {
                    for (int t = 0; t < 2; t++) {
                        long currentCost = dpArray[vIdx][kIdx][xIdx][t];
                        if (currentCost == Long.MAX_VALUE) continue;
                        if (vIdx < vCount) {
                            int posV = vIndices[vIdx];
                            int moves = countSmaller(vIndices, vIdx, posV) + countSmaller(kIndices, kIdx, posV) + countSmaller(xIndices, xIdx, posV);
                            dpArray[vIdx + 1][kIdx][xIdx][1] = Math.min(dpArray[vIdx + 1][kIdx][xIdx][1], currentCost + moves);
                        }
                        if (kIdx < kCount && t == 0) {
                            int posK = kIndices[kIdx];
                            int moves = countSmaller(vIndices, vIdx, posK) + countSmaller(kIndices, kIdx, posK) + countSmaller(xIndices, xIdx, posK);
                            dpArray[vIdx][kIdx + 1][xIdx][0] = Math.min(dpArray[vIdx][kIdx + 1][xIdx][0], currentCost + moves);
                        }
                        if (xIdx < xCount) {
                            int posX = xIndices[xIdx];
                            int moves = countSmaller(vIndices, vIdx, posX) + countSmaller(kIndices, kIdx, posX) + countSmaller(xIndices, xIdx, posX);
                            dpArray[vIdx][kIdx][xIdx + 1][0] = Math.min(dpArray[vIdx][kIdx][xIdx + 1][0], currentCost + moves);
                        }
                    }
                }
            }
        }
        long minTotal = Long.MAX_VALUE;
        for (int i = 0; i < 2; i++) {
            minTotal = Math.min(minTotal, dpArray[vCount][kCount][xCount][i]);
        }
        System.out.println(minTotal);
        sc.close();
    }

    private static int countSmaller(int[] arr, int startIdx, int val) {
        int count = 0;
        for (int i = startIdx; i < arr.length && arr[i] < val; i++) {
            count++;
        }
        return count;
    }
}
